chain = ["def f20(x: int) -> int:\n    return 10 // x\n"]
for k in range(19, 0, -1):
    chain.append(f"def f{k}(x: int) -> int:\n    return f{k + 1}(x) + 1\n")
chain.append("def main() -> int:\n    return f1(0)\n")
